-- =============================================================================
-- 529 — LE CAHIER D'EXERCICES DE 1RE (partie 17)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/1re/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 529 --niveau 1re --fichiers francais.n23a,francais.n23b,francais.n24a,francais.n24b,francais.n25 --suffixe 17 > supabase/contenu/529_exercices_1re_17.sql
--
-- 87 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   francais.n23a           18 exercices · 6 chapitres
--   francais.n23b           18 exercices · 6 chapitres
--   francais.n24a           18 exercices · 6 chapitres
--   francais.n24b           18 exercices · 6 chapitres
--   francais.n25            15 exercices · 5 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('e258a28c-4c3c-5fe8-aac0-14ba6ece8272'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Colette signe enfin de son nom","competence":"se-reperer-temps","situation":"Tu prépares l’oral sur *Les Vrilles de la vigne*. Avant de parler de célébration, place le livre dans la vie de Colette et rappelle les étapes qui l’ont menée à signer seule.","documents":[{"id":"frise","type":"frise","titre":"Colette et son livre","debut":1870,"fin":1955,"pas":5,"evenements":[{"id":"z1","date":1873,"nom":"Naissance"},{"id":"z2","date":1893,"nom":"Mariage avec Willy"},{"id":"z3","date":1908,"nom":"Les Vrilles"},{"id":"z4","date":1954,"nom":"Mort"}]},{"id":"etapes","type":"tableau","titre":"Une femme qui écrit","colonnes":["Étape","Ce qu’elle marque"],"lignes":[["Elle publie sous le nom de son mari, Willy","L’effacement"],["Elle monte sur scène au music-hall pour vivre","?"],["Elle divorce et publie sous son seul nom","Le premier livre signé « Colette » seule"]],"enteteLignes":true}],"questions":[{"enonce":"Sur la frise, touche l’événement qui correspond au premier livre signé « Colette » seule.","aide":"Le titre de ce livre est celui du chapitre : il parle d’une plante qui s’enroule.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent le mariage avec Willy du livre signé « Colette » seule ?","aide":"Repère les deux dates sur la frise, puis soustrais.","type":"nombre","unite":"ans"},{"enonce":"Que marque l’étape du music-hall, dans la case « ? » du tableau ?","aide":"Elle monte sur scène pour gagner sa vie : cela fait parler, mais cela la rend indépendante.","type":"choix","options":[{"id":"a","texte":"La reconnaissance officielle"},{"id":"b","texte":"Le scandale et l’autonomie"},{"id":"c","texte":"Le retour à la maison natale"},{"id":"d","texte":"L’effacement et le silence"}],"multiple":false},{"enonce":"Complète la phrase avec le tableau.","aide":"Relis la première et la dernière ligne du tableau.","type":"trous","segments":["Colette a d’abord publié sous le nom de ",0,", puis elle a ",1," et signé sous son seul nom."],"banque":["voyagé","Sido","divorcé","Willy"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"*Les Vrilles de la vigne* paraît en **1908** : c’est le premier livre que Colette signe de son seul nom."},{"cle":{"type":"nombre","valeur":15,"tolerance":0},"affichage":"15 ans","explication":"1908 − 1893 = **15 ans** : pendant ce temps, ses livres ont paru sous le nom de son mari."},{"cle":{"type":"choix","ids":["b"]},"explication":"Au music-hall, Colette gagne sa vie : c’est à la fois **le scandale et l’autonomie**, deux pas vers sa signature."},{"cle":{"type":"trous","trous":[["willy"],["divorce"]]},"affichage":"Willy · divorcé","explication":"Elle publie d’abord sous le nom de **Willy**, puis elle **divorce** et signe seule."}]$ex$::jsonb),
  ('e258a28c-4c3c-5fe8-aac0-14ba6ece8272'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le jardin de la maison vendue","competence":"analyser-texte","situation":"Lis ce court souvenir écrit « à la manière de » Colette. Repère comment elle célèbre le monde sans l’embellir, puis ce que cette célébration ne cache pas.","documents":[{"id":"souv","type":"texte","genre":"recit","titre":"Un souvenir de jardin","blocs":["Il sentait la pluie d’août sur la poussière chaude. Ma mère se penchait sur un souci, écartait une chenille sans la tuer, parlait à la pivoine qui tardait.","Aujourd’hui la maison est vendue, et le jardin n’est plus qu’une odeur que je garde."],"source":"Texte écrit pour l’exercice, à la manière de Colette"},{"id":"perte","type":"tableau","titre":"Ce qui est célébré, ce qui est perdu","colonnes":["Ce qui est célébré","Ce qui est perdu"],"lignes":[["Le jardin, la maison, les saisons","La mère morte, l’enfance enfuie"],["Le père","Sans œuvre"]],"enteteLignes":true}],"questions":[{"enonce":"Touche les deux noms de fleurs précis que l’on trouve dans ce souvenir.","aide":"Colette n’écrit pas « une fleur » : elle donne le nom exact.","type":"zone","document":"souv","multiple":true},{"enonce":"Touche le vivant non humain que la mère épargne.","aide":"Sido sauve une petite bête qui pourrait abîmer les plantes.","type":"zone","document":"souv","multiple":false},{"enonce":"Touche le mot qui dit que la célébration s’écrit du côté de la perte.","aide":"Il concerne la maison, dans le dernier paragraphe.","type":"zone","document":"souv","multiple":false},{"enonce":"Relie chaque élément de l’enfance à ce qu’il devient.","aide":"Le tableau et le cours donnent ces trois pertes ; la maison est dans le souvenir.","type":"association","gauche":[{"id":"g0","texte":"La maison"},{"id":"g1","texte":"Le père"},{"id":"g2","texte":"Les frères"}],"droite":[{"id":"d0","texte":"Vendue"},{"id":"d1","texte":"Devenus silencieux"},{"id":"d2","texte":"Sans œuvre"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m16","m26"]},"explication":"Elle écrit un **souci** et une **pivoine** : l’émerveillement naît de l’exactitude, non de l’effusion."},{"cle":{"type":"zone","ids":["m19"]},"explication":"La **chenille** est épargnée : pour Sido, le vivant non humain est une société, pas un décor."},{"cle":{"type":"zone","ids":["m33"]},"explication":"La maison est **vendue** : le jardin n’existe plus que dans le souvenir, et c’est pour cela qu’on le regarde si bien."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"La maison est **vendue**, le père reste **sans œuvre**, les frères deviennent **silencieux** : la perte est dite sans éclat."}]$ex$::jsonb),
  ('e258a28c-4c3c-5fe8-aac0-14ba6ece8272'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Célébrer, est-ce embellir ?","competence":"argumenter","situation":"Deux élèves préparent la dissertation « La célébration du monde exclut-elle la perte ? ». Pèse leurs arguments, puis complète le tableau des axes de dissertation.","documents":[{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Élise","emoji":"👧","cote":"gauche"},{"nom":"Malo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Élise","texte":"Pour moi, célébrer le monde, c’est l’embellir : tout doit y être doux."},{"qui":"Malo","texte":"Pourtant Colette écrit « un souci », « une pivoine », jamais « une fleur ». Ce qui compte, c’est l’exactitude."},{"qui":"Élise","texte":"Mais la mère morte, la maison vendue ? Ce n’est pas très joyeux."},{"qui":"Malo","texte":"Justement : elle écrit du côté de la perte, et c’est pour cela qu’elle regarde si bien."}]},{"id":"axes","type":"tableau","titre":"Les axes de dissertation","colonnes":["Question","Ce que permet l’œuvre"],"lignes":[["Célébrer le monde, est-ce l’embellir ?","Non : la précision remplace l’idéalisation"],["L’écriture du souvenir est-elle fidèle ?","?"],["Le regard de l’enfant ou de l’adulte ?","Les deux se superposent"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot par lequel Malo répond à l’idée que célébrer, c’est embellir.","aide":"Il s’oppose à « une fleur » : c’est la qualité d’un nom précis.","type":"zone","document":"deb","multiple":false},{"enonce":"Touche le mot qui explique, pour Malo, la qualité du regard de Colette.","aide":"Elle écrit « du côté de » quelque chose, dit-il.","type":"zone","document":"deb","multiple":false},{"enonce":"Quelle réponse faut-il écrire dans la case « ? » du tableau ?","aide":"Le cours parle de sensation, pas de document.","type":"choix","options":[{"id":"a","texte":"Oui : tout y est un document exact, daté et vérifiable par les archives"},{"id":"b","texte":"Non : elle ne parle jamais de son enfance et n’évoque aucun souvenir"},{"id":"c","texte":"Elle compose, sélectionne, invente : le vrai est de l’ordre de la sensation"},{"id":"d","texte":"On ne peut rien en savoir : tout y est faux et inventé de bout en bout"}],"multiple":false},{"enonce":"Range chaque exemple : ce que Colette écrit, ou ce qu’elle n’écrit pas.","aide":"Elle préfère le nom précis et la sensation exacte aux mots généraux.","type":"categories","categories":[{"id":"c0","texte":"Ce qu’elle écrit"},{"id":"c1","texte":"Ce qu’elle n’écrit pas"}],"items":[{"id":"i0","texte":"Une fleur"},{"id":"i1","texte":"L’odeur exacte de la première pluie sur la poussière chaude"},{"id":"i2","texte":"Un souci, une pivoine"},{"id":"i3","texte":"Le printemps"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m30"]},"explication":"Malo répond par l’**exactitude** : la précision remplace l’idéalisation."},{"cle":{"type":"zone","ids":["m51"]},"explication":"Elle écrit du côté de la **perte** : la lumière du livre tient à cette tension."},{"cle":{"type":"choix","ids":["c"]},"explication":"Colette **compose, sélectionne, invente** : le vrai y est de l’ordre de la sensation, pas du document."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1"}},"explication":"Elle écrit le **souci**, la **pivoine**, l’**odeur exacte** de la pluie ; elle n’écrit pas « une fleur » ni « le printemps » : célébrer, c’est nommer."}]$ex$::jsonb),
  ('5593f9c3-ddac-51da-a68c-442f9305db5c'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Qui aime qui à Trézène ?","competence":"analyser-document","situation":"Tu prépares une fiche sur *Phèdre*. Présente la pièce, puis démêle le triangle des amours.","documents":[{"id":"fiche","type":"fiche","modele":"affiche","entete":"Phèdre","sousTitre":"Jean Racine","emoji":"🎭","lignes":[{"texte":"Genre","valeur":"Tragédie"},{"texte":"Forme","valeur":"Cinq actes, en vers"},{"texte":"Création","valeur":"1677"},{"texte":"Parcours","valeur":"Passion et tragédie"}],"pied":"Alexandrins d’une simplicité extrême","teinte":"violet"},{"id":"amours","type":"chaine","titre":"Le triangle des amours","disposition":"ligne","noeuds":[{"id":"z1","texte":"Phèdre"},{"id":"z2","texte":"Hippolyte"},{"id":"z3","texte":"?"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"}]}],"questions":[{"enonce":"Complète la phrase avec la fiche.","aide":"Tout est sur l’affiche.","type":"trous","segments":["Phèdre est une tragédie en ",0," actes et en ",1,", créée en ",2,"."],"banque":["vers","prose","trois","cinq","1677","1670"]},{"enonce":"Qui faut-il écrire dans la case « ? » : celle qu’Hippolyte aime ?","aide":"C’est une princesse d’une famille ennemie.","type":"choix","options":[{"id":"a","texte":"Pasiphaé"},{"id":"b","texte":"Ismène"},{"id":"c","texte":"Œnone"},{"id":"d","texte":"Aricie"}],"multiple":false},{"enonce":"Touche le personnage dont Phèdre est amoureuse, le fils de son époux Thésée.","aide":"Phèdre est la femme de Thésée : celui qu’elle aime est son beau-fils.","type":"zone","document":"amours","multiple":false},{"enonce":"Relie chaque personnage à son rôle.","aide":"Chaque rôle apparaît dans le cours ; Aricie est déjà dans l’exercice.","type":"association","gauche":[{"id":"g0","texte":"Thésée"},{"id":"g1","texte":"Œnone"},{"id":"g2","texte":"Théramène"},{"id":"g3","texte":"Aricie"}],"droite":[{"id":"d0","texte":"Princesse d’une famille ennemie"},{"id":"d1","texte":"Nourrice de Phèdre"},{"id":"d2","texte":"Roi d’Athènes, réputé mort"},{"id":"d3","texte":"Il fait le récit de la mort d’Hippolyte"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"trous","trous":[["cinq","5"],["vers"],["1677"]]},"affichage":"cinq · vers · 1677","explication":"Une tragédie en **cinq** actes et en **vers**, créée en **1677**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Hippolyte aime **Aricie**, princesse d’une famille ennemie : c’est l’obstacle à l’amour de Phèdre."},{"cle":{"type":"zone","ids":["z2"]},"explication":"Phèdre aime **Hippolyte**, fils de Thésée et d’une Amazone."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g0":"d2","g2":"d3"}},"explication":"**Thésée** est réputé mort, **Œnone** est la nourrice, **Théramène** raconte la mort, **Aricie** est la princesse ennemie."}]$ex$::jsonb),
  ('5593f9c3-ddac-51da-a68c-442f9305db5c'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"De l’aveu à la mort","competence":"se-reperer-temps","situation":"Suis l’enchaînement des événements de la pièce : un aveu, une calomnie, une vengeance. Le tableau donne les étapes dans le désordre.","documents":[{"id":"etapes","type":"tableau","titre":"Les étapes de l’action (en désordre)","colonnes":["Moment","Qui agit","Ce qui en découle"],"lignes":[["Le retour","Thésée","Il n’était pas mort"],["La calomnie","?","Elle accuse Hippolyte d’avoir voulu séduire Phèdre"],["L’aveu","Phèdre","Elle dit son amour à sa nourrice"],["La vengeance","Neptune","Un monstre marin tue Hippolyte"],["La déclaration","Phèdre","Hippolyte la repousse avec horreur"]],"enteteLignes":true}],"questions":[{"enonce":"Qui faut-il écrire dans la case « ? » de la calomnie ?","aide":"C’est la confidente de Phèdre.","type":"choix","options":[{"id":"a","texte":"Théramène"},{"id":"b","texte":"Vénus"},{"id":"c","texte":"Aricie"},{"id":"d","texte":"Œnone"}],"multiple":false},{"enonce":"Remets les cinq étapes dans l’ordre de la pièce.","aide":"La pièce part de l’aveu à la nourrice et finit par la vengeance de Neptune.","type":"ordre","items":[{"id":"a","texte":"Phèdre se déclare à Hippolyte, qui la repousse"},{"id":"b","texte":"Œnone accuse Hippolyte"},{"id":"c","texte":"Phèdre avoue son amour à sa nourrice"},{"id":"d","texte":"Thésée reparaît : il n’était pas mort"},{"id":"e","texte":"Un monstre marin tue Hippolyte"}]},{"enonce":"Complète la fin de la pièce.","aide":"Après la mort d’Hippolyte, elle ne veut plus se taire.","type":"trous","segments":["Phèdre avoue la ",0," et meurt ",1,"."],"banque":["vérité","empoisonnée","calomnie","noyée"]},{"enonce":"Pourquoi Thésée appelle-t-il Neptune contre son fils ?","aide":"Qu’a-t-on dit à Thésée au sujet d’Hippolyte ?","type":"choix","options":[{"id":"a","texte":"Il veut éloigner Aricie"},{"id":"b","texte":"Il a surpris Hippolyte en fuite"},{"id":"c","texte":"Il a lu une lettre de Phèdre"},{"id":"d","texte":"Il croit la calomnie d’Œnone"}],"multiple":false}]}$ex$::jsonb,
