  ('5593f9c3-ddac-51da-a68c-442f9305db5c'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Coupable ou victime ?","competence":"argumenter","situation":"Deux élèves se disputent : Phèdre choisit-elle sa passion ? Lis les vers célèbres du récit de son mal, puis tranche.","documents":[{"id":"vers","type":"texte","genre":"poeme","titre":"Phèdre raconte son mal","blocs":["Je le vis, je rougis, je pâlis à sa vue ;","Un trouble s’éleva dans mon âme éperdue.","","C’est Vénus tout entière à sa proie attachée."],"source":"Jean Racine, *Phèdre* (1677), acte I, scène 3"},{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Jade","emoji":"👧","cote":"gauche"},{"nom":"Noé","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Jade","texte":"Phèdre est coupable : elle a choisi d’aimer le fils de son mari."},{"qui":"Noé","texte":"Elle est surtout une proie : une déesse la poursuit, et son sang la condamne."}]}],"questions":[{"enonce":"Touche les deux verbes qui montrent que le corps de Phèdre la trahit.","aide":"Ce sont deux verbes de couleur et de teint, dans le premier vers.","type":"zone","document":"vers","multiple":true},{"enonce":"Touche le nom de la divinité qui poursuit Phèdre.","aide":"Elle est « tout entière » attachée à sa victime.","type":"zone","document":"vers","multiple":false},{"enonce":"Touche, dans la réplique de Noé, le mot qui fait écho au dernier vers cité.","aide":"Le vers dit « à sa proie attachée ».","type":"zone","document":"deb","multiple":false},{"enonce":"Relie chaque règle ou procédé racinien à sa mise en œuvre.","aide":"Chaque procédé est détaillé dans le cours, section « L’art racinien ».","type":"association","gauche":[{"id":"g0","texte":"Les trois unités"},{"id":"g1","texte":"La bienséance"},{"id":"g2","texte":"Les images fixes"},{"id":"g3","texte":"Le vers"}],"droite":[{"id":"d0","texte":"Alexandrins simples, vocabulaire restreint"},{"id":"d1","texte":"La mort d’Hippolyte est racontée, jamais montrée"},{"id":"d2","texte":"Lieu, temps, action"},{"id":"d3","texte":"Le feu, le sang, le jour, l’ombre"}]},{"enonce":"Quelle conclusion de dissertation ces vers appuient-ils le mieux ?","aide":"Le corps trahit, la déesse poursuit : mais Phèdre parle et avoue.","type":"choix","options":[{"id":"a","texte":"Culpabilité et innocence sont inséparables chez Phèdre"},{"id":"b","texte":"Phèdre n’éprouve aucune passion pour Hippolyte"},{"id":"c","texte":"Phèdre est entièrement coupable de son amour"},{"id":"d","texte":"Phèdre est entièrement innocente et sans faute"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4","m6"]},"explication":"Elle **rougit** et **pâlit** : la passion se lit sur le corps, sans que Phèdre le décide."},{"cle":{"type":"zone","ids":["m20"]},"explication":"**Vénus** persécute Phèdre : la passion est une maladie subie, non un choix."},{"cle":{"type":"zone","ids":["m17"]},"explication":"Noé parle de **proie** comme Racine : Phèdre est la victime d’une force qui la dépasse."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g0":"d2","g2":"d3"}},"explication":"**Unités** : lieu, temps, action ; **bienséance** : récit de la mort ; **images fixes** : feu, sang, jour, ombre ; **vers** : simplicité."},{"cle":{"type":"choix","ids":["a"]},"explication":"Racine peint la passion comme une maladie subie : **culpabilité et innocence sont inséparables**, c’est la lecture janséniste."}]$ex$::jsonb),
