r l’ordre établi"},{"id":"b","texte":"Qu’il voulait détruire la Bastille avant 1789"},{"id":"c","texte":"Qu’il trouvait la pièce sans aucune portée politique"},{"id":"d","texte":"Qu’il admirait Figaro, le valet"}],"multiple":false}]}$ex$::jsonb,
