   $ex${"titre":"Une journée sans intrigue","competence":"analyser-texte","situation":"Rien n’arrive dans cette pièce : le temps est rempli par des rituels. Lis cette courte scène écrite pour l’exercice, à la manière de Beckett, puis classe ce qui s’y répète.","documents":[{"id":"scene","type":"texte","genre":"theatre","titre":"Un réveil de Winnie","blocs":[{"didascalie":"Une sonnerie aiguë perce le silence. Winnie, enterrée jusqu’à la taille, ouvre les yeux."},{"personnage":"Winnie","replique":"Encore un jour divin. Un peu de prière, la brosse à dents, le peigne. Dans le sac, tout au fond, le revolver."},{"didascalie":"Derrière le mamelon, Willie lit son journal."}],"source":"Texte écrit pour l’exercice, à la manière de Beckett"},{"id":"rit","type":"tableau","titre":"Les rituels de la pièce","colonnes":["Rituel","Ce qu’il occupe"],"lignes":[["La sonnerie qui réveille","Elle règle le jour"],["La prière, la brosse à dents, le peigne","Le temps"],["Le revolver dans le sac","?"],["L’espoir que Willie réponde","L’adresse à l’autre"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui règle le jour de Winnie.","aide":"C’est un bruit qui la réveille.","type":"zone","document":"scene","multiple":false},{"enonce":"Touche les trois mots qui disent ce qui occupe son temps.","aide":"Un geste de piété, un objet pour les dents, un objet pour les cheveux.","type":"zone","document":"scene","multiple":true},{"enonce":"Que représente le revolver (la case « ? ») ?","aide":"Il reste dans le sac, et la pièce n’avance pas vers un dénouement.","type":"choix","options":[{"id":"a","texte":"Un cadeau de Willie"},{"id":"b","texte":"Un souvenir de guerre"},{"id":"c","texte":"Une arme qui servira au dénouement"},{"id":"d","texte":"Une possibilité jamais choisie"}],"multiple":false},{"enonce":"Qu’est-ce qui remplace l’intrigue dans cette pièce ?","aide":"Relis le titre du tableau.","type":"choix","options":[{"id":"a","texte":"Une enquête sur le passé de Winnie"},{"id":"b","texte":"