   $ex${"titre":"Barbare, selon qui ?","competence":"analyser-texte","situation":"Montaigne a rencontré à Rouen des Tupinambas du Brésil. Lis sa phrase célèbre (orthographe modernisée), puis oppose leurs pratiques à celles de l’Europe.","documents":[{"id":"cit","type":"texte","genre":"source","titre":"La phrase célèbre","blocs":["Chacun appelle barbarie ce qui n’est pas de son usage."],"source":"Montaigne, *Essais*, « Des Cannibales » (orthographe modernisée)"},{"id":"comp","type":"tableau","titre":"Chez eux, chez nous","colonnes":["Où ?","Ce qui se pratique"],"lignes":[["Chez les Tupinambas","L’anthropophagie rituelle sur un ennemi mort"],["En Europe","?"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot que chacun applique à ce qui lui est étranger.","aide":"C’est le mot que l’on dit à propos de « l’autre ».","type":"zone","document":"cit","multiple":false},{"enonce":"Que faut-il écrire dans la case « ? » : la pratique européenne à laquelle Montaigne oppose l’anthropophagie rituelle ?","aide":"Chez les Tupinambas, l’ennemi est mort ; en Europe, il est…","type":"choix","options":[{"id":"a","texte":"Le commerce des épices avec l’Orient"},{"id":"b","texte":"La torture de vivants, au nom de la religion"},{"id":"c","texte":"Les banquets des princes dans leurs coches"},{"id":"d","texte":"Les tournois de la noblesse"}],"multiple":false},{"enonce":"Que dit le mot « usage » dans la phrase ?","aide":"Pense à ce que « barbare » décrit, d’après la phrase.","type":"choix","options":[{"id":"a","texte":"Que les peuples utilisent tous les mêmes outils"},{"id":"b","texte":"Que « barbare » juge l’habitude de celui qui parle"},{"id":"c","texte":"Que Montaigne trouve l’usage des Tupinambas absurde"},{"id":"d","texte":"Que le mot « barbare » est un terme scientifique"}],"multiple":false},{"enonce":"Quel est l’effet de cette comparaison sur le lecteur européen ?","aide":"C’est le premier grand texte à retourner le regard contre l’Europe.","type":"choix","options":[{"id":"a","texte":"Il doit admirer sans réserve les Tupinambas"},{"id":"b","texte":"Il doit se regarder lui-même avant de juger l’autre"},{"id":"c","texte":"Il doit renoncer à toute règle morale"},{"id":"d","texte":"Il doit refuser de lire les récits de voyage"}],"multiple":false}]}$ex$::jsonb,
