   $ex${"titre":"Un bon sauvage qui tend un miroir","competence":"argumenter","situation":"Montaigne décrit une société parfaite en apparence. Est-ce de l’ethnographie ou une manière de critiquer la France ? Lis le résumé, puis suis le débat.","documents":[{"id":"res","type":"texte","genre":"article","titre":"Le portrait des Tupinambas","blocs":["Dans son portrait, Montaigne décrit une société sans commerce, sans écriture, sans magistrature, sans propriété.","Le tableau est trop beau pour être exact : il sert à faire voir, par contraste, une France déchirée par les guerres de religion."],"source":"Résumé écrit pour l’exercice"},{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Adam","emoji":"👦","cote":"gauche"},{"nom":"Zoé","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Adam","texte":"Montaigne raconte fidèlement ce qui se passe au Brésil."},{"qui":"Zoé","texte":"Il sait que son portrait est idéalisé : c’est un miroir tendu à l’Europe."}]}],"questions":[{"enonce":"Touche les quatre éléments que la société décrite ne connaît pas.","aide":"Ils sont tous précédés de « sans ».","type":"zone","document":"res","multiple":true},{"enonce":"Touche le mot qui nomme ce qui déchire la France à l’époque de Montaigne.","aide":"Le conflit est religieux.","type":"zone","document":"res","multiple":false},{"enonce":"Touche le mot de Zoé qui définit la fonction du portrait.","aide":"Un objet qui renvoie notre propre image.","type":"zone","document":"deb","multiple":false},{"enonce":"Quelle est la fonction de ce portrait idéalisé ?","aide":"Le résumé dit « par contraste ».","type":"choix","options":[{"id":"a","texte":"Une copie d’un récit de voyage de Jean-Jacques Rousseau"},{"id":"b","texte":"Une publicité pour de futurs voyages vers l’Amérique"},{"id":"c","texte":"Une utopie critique, qui rend visibles les vices de la France"},{"id":"d","texte":"Un reportage fidèle et précis sur la vie au Brésil"}],"multiple":false},{"enonce":"Relie chaque