  ('c214824b-08e1-5fba-b106-ad1746c0b16d'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un héros qu’on suit sans l’approuver","competence":"analyser-texte","situation":"Deux lycéens se disputent sur Julien : faut-il l’admirer ? Lis un passage écrit à la manière de Stendhal, puis tranche.","documents":[{"id":"scene","type":"texte","genre":"recit","titre":"Une soirée d’Armand","blocs":["Armand, fils d’un tonnelier, avait fixé l’heure de son audace : avant la fin de la soirée, il prendrait la main de la jeune veuve. Il comptait les minutes et calculait son effet. Ce n’était pas l’amour qui le faisait trembler, c’était la peur d’être ridicule.","Demain il serait trop tard. Fallait-il rester toute sa vie un fils de tonnelier ? Le notaire, ce soir-là, le trouva fort aimable et ne vit rien."],"source":"Texte écrit pour l’exercice, à la manière de Stendhal"},{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Chloé","emoji":"👧","cote":"gauche"},{"nom":"Mehdi","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Chloé","texte":"Le narrateur ne montre que ce que fait Armand, jamais ce qu’il pense."},{"qui":"Mehdi","texte":"Faux : on entend ses calculs et sa peur, et pourtant le narrateur sourit de lui."}]}],"questions":[{"enonce":"Touche les deux verbes qui montrent que le héros calcule.","aide":"Cherche ce qu’il fait des minutes et de son effet.","type":"zone","document":"scene","multiple":true},{"enonce":"Les pensées d’Armand (« Demain il serait trop tard… ») ne sont pas entre guillemets. Quel procédé les fait entendre dans le récit ?","aide":"La pensée passe dans le récit sans verbe introducteur.","type":"choix","options":[{"id":"a","texte":"La description d’un décor"},{"id":"b","texte":"La prosopopée"},{"id":"c","texte":"Le discours indirect libre"},{"id":"d","texte":"Le discours direct"}],"multiple":false},{"enonce":"D’après le passage, qui a raison dans le débat ?","aide":"Relis la phrase sur la peur d’être ridicule et celle du notaire.","type":"choix","options":[{"id":"a","texte":"Chloé : le texte ne dévoile aucune des pensées du héros"},{"id":"b","texte":"Chloé : le narrateur approuve en tout ce que fait le héros"},{"id":"c","texte":"Mehdi : le narrateur ne porte jamais aucun jugement"},{"id":"d","texte":"Mehdi : le texte donne accès à ses pensées tout en le tournant en ironie"}],"multiple":false},{"enonce":"Range ces traits de Julien : ce qui le condamne ou ce qui le grandit ?","aide":"Le roman refuse de trancher : il montre les deux faces.","type":"categories","categories":[{"id":"c0","texte":"Ce qui le condamne"},{"id":"c1","texte":"Ce qui le grandit"}],"items":[{"id":"i0","texte":"Il ment et calcule par ambition"},{"id":"i1","texte":"Il est courageux"},{"id":"i2","texte":"Il tire sur une femme qu’il aime"},{"id":"i3","texte":"Il est loyal envers Pirard"},{"id":"i4","texte":"Il est sincère avec Fouqué"}]},{"enonce":"Relie chaque apport du roman à ce qu’il devient.","aide":"Un apport pour le personnage, un pour la voix, un pour le point de vue.","type":"association","gauche":[{"id":"g0","texte":"Le héros ambitieux"},{"id":"g1","texte":"L’ironie stendhalienne"},{"id":"g2","texte":"La focalisation interne serrée"}],"droite":[{"id":"d0","texte":"Une voix narrative à distance"},{"id":"d1","texte":"On suit les calculs du personnage"},{"id":"d2","texte":"Le modèle de tout le XIXe siècle"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m27","m31"]},"explication":"Armand **comptait** les minutes et **calculait** son effet : l’ambition règle chacun de ses gestes."},{"cle":{"type":"choix","ids":["c"]},"explication":"C’est le **discours indirect libre** : la pensée du personnage entre dans la voix du narrateur."},{"cle":{"type":"choix","ids":["d"]},"explication":"**Mehdi** : on lit les calculs et la peur d’Armand de l’intérieur, mais le narrateur garde la distance de l’ironie."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c1","i4":"c1"}},"explication":"Julien **ment** et **tire sur une femme qu’il aime**, mais il est **courageux**, **loyal** et **sincère** : un héros ambivalent."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"Le **héros ambitieux** fait école, l’**ironie** installe la distance, la **focalisation interne** nous enferme dans ses calculs."}]$ex$::jsonb),
