   $ex${"titre":"Six titres latins, un récit rétrospectif","competence":"analyser-document","situation":"Les six sections du livre portent des titres latins. Retrouve celui qui manque et ce que chacun annonce, puis explique la forme du récit.","documents":[{"id":"titres","type":"chaine","titre":"Les six sections du livre","disposition":"colonne","noeuds":[{"id":"z1","texte":"Animula vagula blandula"},{"id":"z2","texte":"Varius multiplex multiformis"},{"id":"z3","texte":"Tellus stabilita"},{"id":"z4","texte":"?"},{"id":"z5","texte":"Disciplina augusta"},{"id":"z6","texte":"Patientia"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z5"},{"de":"z5","a":"z6"}]},{"id":"resume","type":"texte","genre":"recit","titre":"Le résumé du livre","blocs":["Un empereur malade écrit à son petit-fils adoptif, alors adolescent. Il reprend toute sa vie, de ses débuts de soldat jusqu’à la mort qui approche. Le récit est donc rétrospectif : l’homme qui parle sait déjà comment tout finit."],"source":"Résumé écrit pour l’exercice"}],"questions":[{"enonce":"Quel titre faut-il écrire à la place de la case « ? », sachant que cette section raconte le siècle d’or et Antinoüs ?","aide":"Le titre latin reprend la formule « le siècle d’or ».","type":"choix","options":[{"id":"a","texte":"Imperium aeternum"},{"id":"b","texte":"Pax augusta"},{"id":"c","texte":"Saeculum aureum"},{"id":"d","texte":"Fortuna varia"}],"multiple":false},{"enonce":"Relie chaque titre à ce qu’il annonce.","aide":"Traduis chaque titre en mot clé : terre, siècle d’or, discipline, patience.","type":"association","gauche":[{"id":"g0","texte":"Tellus stabilita"},{"id":"g1","texte":"Saeculum aureum"},{"id":"g2","texte":"Disciplina augusta"},{"id":"g3","texte":"Patientia"}],"droite":[{"id":"d0","texte":"Le siècle d’or et Antinoüs"},{"id":"d1","texte":"La terre pacifiée"},{"id":"d2","texte":"La maladie et la mort"},{"id":"d3","texte":"L’ordre impérial"}]},{"enonce":"Touche les deux mots qui disent que le récit regarde en arrière.","aide":"Cherche un verbe et un adjectif.","type":"zone","document":"resume","multiple":true},{"enonce":"À quelle personne est écrit le livre ?","aide":"Hadrien écrit une lettre sur sa propre vie.","type":"choix","options":[{"id":"a","texte":"À la première personne"},{"id":"b","texte":"À la troisième personne"},{"id":"c","texte":"Il alterne entre plusieurs narrateurs"},{"id":"d","texte":"À la deuxième personne du pluriel"}],"multiple":false}]}$ex$::jsonb,
