  ('28e61bf4-ac4c-530e-9568-c9471421c5fd'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Entre l’érudition et la magie","competence":"analyser-texte","situation":"Yourcenar disait vouloir un « pied dans l’érudition, l’autre dans la magie ». Voici un passage écrit à sa manière : repère la politique, l’intime et le style.","documents":[{"id":"pass","type":"texte","genre":"recit","titre":"Une voix d’empereur","blocs":["J’ai appris tard que gouverner consiste à déplacer les bornes le moins possible. Les légions que j’ai rappelées derrière le fleuve m’ont valu des railleries ; je les préfère aux victoires qui vident un empire.","Ce soir, mon corps me prévient : il est des chevaux que je ne monterai plus, des eaux dont je ne goûterai plus la fraîcheur."],"source":"Texte écrit pour l’exercice, à la manière de Yourcenar"},{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Noé","emoji":"👦","cote":"gauche"},{"nom":"Sarah","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Noé","texte":"C’est une biographie : tout y est vrai, daté et sourcé."},{"qui":"Sarah","texte":"Non, c’est un roman : une romancière fait parler Hadrien à la première personne."}]}],"questions":[{"enonce":"Touche les deux mots qui montrent la politique de consolidation d’Hadrien.","aide":"Il ne conquiert pas : il arrête, il recule.","type":"zone","document":"pass","multiple":true},{"enonce":"Touche les deux mots qui relèvent des notations intimes du corps.","aide":"Pense à ce qu’un cavalier perd quand il vieillit.","type":"zone","document":"pass","multiple":true},{"enonce":"Qu’est-ce qui prouve que ce livre n’est pas une simple biographie ?","aide":"Qui dit « je » dans le passage ?","type":"choix","options":[{"id":"a","texte":"Il n’y est jamais question d’histoire romaine"},{"id":"b","texte":"Il est écrit par un historien du XXe siècle"},{"id":"c","texte":"Hadrien y raconte l’histoire d’un autre empereur"},{"id":"d","texte":"Une romancière fait parler Hadrien à la première personne"}],"multiple":false},{"enonce":"Relie chaque trait de style à son effet.","aide":"Chaque trait donne un ton ou un contenu.","type":"association","gauche":[{"id":"g0","texte":"La phrase ample, aphoristique"},{"id":"g1","texte":"Les grandes fresques"},{"id":"g2","texte":"Les notations intimes"}],"droite":[{"id":"d0","texte":"Guerres, voyages, réformes"},{"id":"d1","texte":"Le goût de l’eau, la fatigue, le sommeil"},{"id":"d2","texte":"La gravité"}]},{"enonce":"Le livre est autant une ___ qu’un roman historique.","aide":"Le cours dit que le livre dépasse la reconstitution historique.","type":"choix","options":[{"id":"a","texte":"Chronique militaire de la conquête des provinces romaines"},{"id":"b","texte":"Enquête policière sur la mort d’Antinoüs dans le Nil"},{"id":"c","texte":"Biographie savante de l’empereur Marc Aurèle"},{"id":"d","texte":"Méditation sur le pouvoir, l’art, le corps et la mort"}],"multiple":false}]}$ex$::jsonb,
