  ('46bdc52b-5a4e-5a5c-9667-fe6e4b302d88'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La gomme et l’homme sans nom","competence":"analyser-texte","situation":"Tu étudies un passage écrit à la manière du Nouveau Roman : pas de héros, pas de psychologie, mais un objet décrit comme une figure géométrique.","documents":[{"id":"gomme","type":"texte","genre":"recit","titre":"Sur la table","blocs":["Sur la table, une gomme : un parallélépipède blanc, dont l’une des faces est entamée en biais. Elle est posée à quatre centimètres du bord.","Un homme entre. On ne sait ni son nom, ni ce qu’il pense. Il regarde la gomme."],"source":"Texte écrit pour l’exercice, à la manière du Nouveau Roman"},{"id":"refus","type":"tableau","titre":"Ce qui disparaît","colonnes":["Ce qui disparaît","Ce que cela signifie"],"lignes":[["Le personnage","Plus de nom parfois, plus de portrait, plus de biographie"],["L’intrigue","?"],["La psychologie","Les motivations cèdent aux sensations et aux objets"],["L’auteur omniscient","Personne ne domine plus le récit"]],"enteteLignes":true}],"questions":[{"enonce":"Touche les deux mots qui décrivent la gomme comme une forme mesurée.","aide":"Cherche un mot de géométrie et une unité de mesure.","type":"zone","document":"gomme","multiple":true},{"enonce":"Touche les deux mots qui montrent que le personnage n’a ni identité ni psychologie.","aide":"Le narrateur avoue ce qu’il ne sait pas.","type":"zone","document":"gomme","multiple":true},{"enonce":"Que faut-il écrire en face de « L’intrigue » ?","aide":"L’intrigue classique avec début, milieu et fin disparaît.","type":"choix","options":[{"id":"a","texte":"Une intrigue encore plus compliquée, pleine de coups de théâtre"},{"id":"b","texte":"Plus de chronologie claire ni de dénouement : le récit tourne"},{"id":"c","texte":"Une enquête menée du début à la fin par un détective"},{"id":"d","texte":"Un dénouement toujours donné par un narrateur omniscient"}],"multiple":false},{"enonce":"Relie chaque élément mis à la place à sa forme.","aide":"Pense à ce qui remplace le personnage et l’intrigue.","type":"association","gauche":[{"id":"g0","texte":"La description"},{"id":"g1","texte":"La répétition et la variation"},{"id":"g2","texte":"Le lecteur"}],"droite":[{"id":"d0","texte":"Portée à un degré inédit : objets décrits pendant des pages"},{"id":"d1","texte":"Il reconstitue et accepte de ne pas tout savoir"},{"id":"d2","texte":"Des principes de composition, chez Simon et Butor"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6","m22"]},"explication":"Le **parallélépipède** et les quatre **centimètres** : la description est géométrique, sans métaphore."},{"cle":{"type":"zone","ids":["m33","m38"]},"explication":"On ne connaît ni son **nom**, ni ce qu’il **pense** : plus de portrait, plus de psychologie."},{"cle":{"type":"choix","ids":["b"]},"explication":"L’intrigue disparaît : **plus de chronologie claire, plus de dénouement**."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"La **description** devient centrale, la **répétition** compose le livre, le **lecteur** fait le travail."}]$ex$::jsonb),
  ('46bdc52b-5a4e-5a5c-9667-fe6e4b302d88'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le Nouveau Roman détruit-il le roman ?","competence":"argumenter","situation":"Deux élèves débattent : le Nouveau Roman détruit-il le roman ? Lis un passage à la deuxième personne, à la manière de Butor, pour les départager.","documents":[{"id":"train","type":"texte","genre":"recit","titre":"Dans le train","blocs":["Vous avez posé la valise sur le porte-bagages. Vous regardez le contrôleur qui s’éloigne dans le couloir. Vous ne savez pas encore pourquoi vous avez pris ce train."],"source":"Texte écrit pour l’exercice, à la manière de Butor"},{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Lucas","emoji":"👦","cote":"gauche"},{"nom":"Zoé","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Lucas","texte":"Plus de personnage, plus d’intrigue : le Nouveau Roman détruit le roman."},{"qui":"Zoé","texte":"Il le déplace : montrer les conventions comme conventions, c’est encore écrire un roman."}]}],"questions":[{"enonce":"Touche les trois pronoms qui fixent la personne du récit.","aide":"Le pronom se répète au début de chaque phrase.","type":"zone","document":"train","multiple":true},{"enonce":"Qu’est-ce qui, dans ce passage, donne raison à Zoé ?","aide":"Le texte raconte-t-il encore quelque chose ?","type":"choix","options":[{"id":"a","texte":"Il décrit longuement les pensées profondes du voyageur"},{"id":"b","texte":"Il ne contient plus aucun mot de la langue française courante"},{"id":"c","texte":"Il raconte une intrigue complète avec un dénouement clair"},{"id":"d","texte":"Sans nom ni psychologie, il reste un récit avec lieu et gestes"}],"multiple":false},{"enonce":"Range chaque élément : refusé ou mis à la place par le Nouveau Roman ?","aide":"Pense à ce que les auteurs rejettent, puis à ce qu’ils inventent.","type":"categories","categories":[{"id":"c0","texte":"Refusé"},{"id":"c1","texte":"Mis à la place"}],"items":[{"id":"i0","texte":"L’intrigue avec dénouement"},{"id":"i1","texte":"La description minutieuse"},{"id":"i2","texte":"Le lecteur qui reconstitue"},{"id":"i3","texte":"Le personnage biographié"},{"id":"i4","texte":"La répétition et la variation"},{"id":"i5","texte":"L’auteur omniscient"}]},{"enonce":"Relie chaque auteur à son texte.","aide":"Deux manifestes et un roman.","type":"association","gauche":[{"id":"g0","texte":"Nathalie Sarraute"},{"id":"g1","texte":"Alain Robbe-Grillet"},{"id":"g2","texte":"Michel Butor"}],"droite":[{"id":"d0","texte":"Pour un nouveau roman"},{"id":"d1","texte":"L’Ère du soupçon"},{"id":"d2","texte":"La Modification"}]},{"enonce":"Quelle conclusion de dissertation ce chapitre permet-il d’appuyer ?","aide":"Le Nouveau Roman est un « air de famille », pas une école.","type":"choix","options":[{"id":"a","texte":"Le Nouveau Roman a supprimé définitivement le genre du roman"},{"id":"b","texte":"Le Nouveau Roman revient au roman psychologique du XIXe siècle"},{"id":"c","texte":"Une esthétique et une vision du monde : un réel d’objets et d’incertitude"},{"id":"d","texte":"Le Nouveau Roman est une école organisée avec un chef et un programme"}],"multiple":false}]}$ex$::jsonb,
