t.","type":"categories","categories":[{"id":"c0","texte":"La boue"},{"id":"c1","texte":"L’or"}],"items":[{"id":"i0","texte":"Les vieillards et les mendiantes"},{"id":"i1","texte":"La charogne"},{"id":"i2","texte":"Les images qui transfigurent"},{"id":"i3","texte":"Le rythme des vers"},{"id":"i4","texte":"La ville sale"},{"id":"i5","texte":"Le sonnet ciselé"}]},{"enonce":"La modernité est-elle une esthétique de la laideur ?","aide":"Retiens la formule du cours.","type":"choix","options":[{"id":"a","texte":"Oui : elle préfère le laid au beau"},{"id":"b","texte":"Non : elle cherche seulement des sujets nobles"},{"id":"c","texte":"Non : une esthétique de la transformation"},{"id":"d","texte":"Oui : elle refuse toute forme"}],"multiple":false}]}$ex$::jsonb,
