,"aide":"Pense au sens propre des alcools.","type":"association","gauche":[{"id":"g0","texte":"Ce qui enivre"},{"id":"g1","texte":"Ce qui brûle"},{"id":"g2","texte":"Ce qui distille"}],"droite":[{"id":"d0","texte":"L’ivresse, joie ou douleur d’amour"},{"id":"d1","texte":"Des vies et des villes distillées en poèmes courts"},{"id":"d2","texte":"La passion, la souffrance"}]}]}$ex$::jsonb,
