   $ex${"titre":"Un dimanche où il ne se passe rien","competence":"se-reperer-temps","situation":"Pour ton exposé, tu veux montrer comment la pièce est construite : suis son plan, puis dis ce qui s’y passe vraiment.","documents":[{"id":"plan","type":"chaine","titre":"Le plan de la pièce","disposition":"colonne","noeuds":[{"id":"z1","texte":"Prologue : Louis parle au spectateur"},{"id":"z2","texte":"Première partie"},{"id":"z3","texte":"Intermède"},{"id":"z4","texte":"Seconde partie"},{"id":"z5","texte":"?"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z5"}],"source":"Schéma rédigé pour l’exercice"}],"questions":[{"enonce":"Que faut-il écrire dans la dernière case « ? » du plan ?","aide":"La pièce est l’histoire d’un aveu qui n’aura pas lieu.","type":"choix","options":[{"id":"a","texte":"Épilogue : la famille se réconcilie autour de Louis, qui promet de revenir bientôt"},{"id":"b","texte":"Épilogue : Louis repart sans avoir rien dit, et un cri est raconté au conditionnel"},{"id":"c","texte":"Épilogue : Louis annonce enfin sa mort à sa famille réunie"},{"id":"d","texte":"Épilogue : Louis décide de rester vivre auprès des siens"}],"multiple":false},{"enonce":"Touche l’étape où le spectateur apprend que Louis va mourir.","aide":"Le spectateur le sait avant tous les personnages.","type":"zone","document":"plan","multiple":false},{"enonce":"Que se passe-t-il pendant le dimanche, entre le prologue et l’épilogue ?","aide":"La pièce comporte-t-elle des rebondissements ? Le cours dit le contraire.","type":"choix","options":[{"id":"a","texte":"Louis décide de rester vivre auprès des siens"},{"id":"b","texte":"Louis annonce enfin sa mort à sa mère"},{"id":"c","texte":"On déjeune, on se dispute, on évoque le passé : il ne se passe rien"},{"id":"d","texte":"Un coup de théâtre bouleverse toute la famille et change le cours du dimanche"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["b"]},"explication":"À la fin, Louis **repart sans avoir rien dit** ; l’épilogue raconte **au conditionnel** un cri qu’il n’a jamais poussé."},{"cle":{"type":"zone","ids":["z1"]},"explication":"Dès le **prologue**, Louis annonce sa mort prochaine au seul spectateur : la famille, elle, ne l’apprendra jamais."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Il ne se passe rien** : on déjeune, on se dispute, on évoque le passé, quelqu’un propose une promenade en voiture."}]$ex$::jsonb),
  ('4bed4876-8d60-5da7-ad5b-c6545cb63202'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"On parle pour ne rien dire","competence":"argumenter","situation":"Deux élèves se disputent sur la langue de Lagarce. Lis la scène écrite pour l’exercice, puis tranche en t’appuyant sur ses mots.","documents":[{"id":"scene","type":"texte","genre":"theatre","titre":"Après le déjeuner","blocs":[{"didascalie":"Deux sœurs, une fois le repas terminé. Leur frère vient de repartir."},{"personnage":"La Sœur","replique":"Je voulais dire — enfin, ce n’est pas ce que je voulais dire — qu’il avait l’air heureux de venir. Ou plutôt non, qu’il n’avait pas l’air malheureux."},{"personnage":"Le Frère","replique":"Enfin, tu dis ça, mais on ne sait pas. On parle, on parle, et on ne dit rien."}],"source":"Texte écrit pour l’exercice, à la manière de Lagarce"},{"id":"deb","type":"dialogue","titre":"Le débat de la classe","modele":"bulles","participants":[{"nom":"Inès","emoji":"👧","cote":"gauche"},{"nom":"Malik","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Inès","texte":"Cette famille parle sans arrêt : c’est donc qu’elle se dit tout."},{"qui":"Malik","texte":"Au contraire : on parle sans arrêt pour ne pas dire l’essentiel."}]}],"questions":[{"enonce":"Touche les deux mots par lesquels la sœur corrige ce qu’elle vient de dire.","aide":"Cherche le mot qui annonce une rectification, puis celui qui rejette la première idée.","type":"zone","document":"scene","multiple":true},{"enonce":"Quelle lecture la scène soutient-elle le mieux ?","aide":"Relis la dernière phrase du Frère.","type":"choix","options":[{"id":"a","texte":"Celle d’Inès : la famille se dit tout en parlant"},{"id":"b","texte":"Celle d’Inès : le frère écoute attentivement chaque mot"},{"id":"c","texte":"Celle de Malik : on parle beaucoup pour éviter l’essentiel"},{"id":"d","texte":"Aucune : la scène n’a rien à voir avec ce débat"}],"multiple":false},{"enonce":"Relie chaque procédé de la pièce à son effet.","aide":"Demande-toi ce que chaque procédé fait à la parole des personnages.","type":"association","gauche":[{"id":"g0","texte":"Les phrases qui se reprennent et se corrigent"},{"id":"g1","texte":"Les monologues qui coexistent sans se répondre"},{"id":"g2","texte":"Le « juste » du titre"}],"droite":[{"id":"d0","texte":"La parole cherche le mot juste et le manque"},{"id":"d1","texte":"Une catastrophe minimisée, jamais prononcée"},{"id":"d2","texte":"Personne n’écoute vraiment"}]},{"enonce":"Pour une dissertation, que dit le cours sur la question « Louis est-il lâche, ou protège-t-il les siens ? »","aide":"La pièce ne donne pas de verdict sur Louis.","type":"choix","options":[{"id":"a","texte":"Le texte ne permet pas d’en parler"},{"id":"b","texte":"Le texte tranche : Louis est lâche"},{"id":"c","texte":"Le texte tranche : Louis protège sa famille"},{"id":"d","texte":"Le texte refuse de trancher"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m34","m35"]},"explication":"La sœur se reprend avec « **plutôt** » et « **non** » : c’est la langue de Lagarce, qui se corrige en direct et cherche le mot juste."},{"cle":{"type":"choix","ids":["c"]},"explication":"« On parle, on parle, et on ne dit **rien** » donne raison à **Malik** : dans cette famille, on parle sans arrêt pour ne pas dire l’essentiel."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"Les **reprises** disent le mot cherché et manqué, les **monologues** juxtaposent des paroles sans écoute, le **« juste »** du titre minimise la catastrophe."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le texte **refuse de trancher** : les deux lectures restent possibles, et c’est ce qui nourrit la dissertation."}]$ex$::jsonb),
