  ('6781922a-51da-570b-b31f-c643352d5b32'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le rire de Rabelais est-il innocent ?","competence":"argumenter","situation":"Sujet : « Le rire chez Rabelais n’est-il qu’un divertissement ? » Compare les deux éducations, repère le procédé comique, puis tranche.","documents":[{"id":"educ","type":"tableau","titre":"Les deux éducations de Gargantua","colonnes":["Critère","Les sorbonnards","Ponocrates"],"lignes":[["La méthode","Apprendre par cœur des livres inutiles","?"],["Le ressort","La contrainte","L’apprentissage par le plaisir"]],"enteteLignes":true,"source":"Tableau rédigé pour l’exercice"},{"id":"ecole","type":"texte","genre":"recit","titre":"Une journée à l’ancienne école","blocs":["Le jeune géant se levait tard, récitait son latin de cuisine sans en saisir un mot, puis on lui faisait répéter la leçon, encore et encore, pendant des années.","On ne lui parlait ni de jeux, ni de promenade, ni de la nature : un livre, un fouet, et le soir un grand sommeil."],"source":"Texte écrit pour l’exercice, à la manière de Rabelais (langue modernisée)"}],"questions":[{"enonce":"Touche les deux verbes qui disent la méthode des sorbonnards.","aide":"Un verbe dit ce que le jeune géant fait de ses leçons, l’autre ce qu’on lui fait faire.","type":"zone","document":"ecole","multiple":true},{"enonce":"Que faut-il écrire dans la case « ? » pour la méthode de Ponocrates ?","aide":"Il s’oppose point par point aux sorbonnards.","type":"choix","options":[{"id":"a","texte":"Un apprentissage par cœur, mais plus court"},{"id":"b","texte":"Un enseignement réservé aux seuls moines"},{"id":"c","texte":"Des journées entières de récitation silencieuse, sans exercice ni promenade"},{"id":"d","texte":"Une journée réglée : exercice physique, lectures commentées, observation directe"}],"multiple":false},{"enonce":"Touche la case qui dit ce qui fait avancer Gargantua chez Ponocrates.","aide":"C’est la ligne « Le ressort ».","type":"zone","document":"educ","multiple":false},{"enonce":"Range chaque élément : est-ce un procédé du rire ou une cible de la satire ?","aide":"Un procédé est une façon de faire rire ; une cible est ce dont on se moque.","type":"categories","categories":[{"id":"c0","texte":"Procédé du rire"},{"id":"c1","texte":"Cible de la satire"}],"items":[{"id":"i0","texte":"Les noms parlants"},{"id":"i1","texte":"La scolastique"},{"id":"i2","texte":"La guerre de conquête"},{"id":"i3","texte":"La religion formaliste"},{"id":"i4","texte":"Les énumérations vertigineuses"},{"id":"i5","texte":"Le latin de cuisine"}]},{"enonce":"Quelle conclusion le cours appuie-t-il sur le rire de Rabelais ?","aide":"Les trois autres réponses font du rire un ornement.","type":"choix","options":[{"id":"a","texte":"C’est une méthode : il désacralise l’autorité et rend le savoir joyeux"},{"id":"b","texte":"C’est une pause entre deux passages sérieux"},{"id":"c","texte":"C’est un simple divertissement sans portée, destiné à faire passer le temps"},{"id":"d","texte":"C’est un moyen de cacher la vérité au lecteur"}],"multiple":false}]}$ex$::jsonb,
